+  // ---------------------------------------------------------------------------
+  // File events
+  // ---------------------------------------------------------------------------
+
+  /**
+   * Broadcast file changes to all projects. Each project selectively bumps projectVersion (Volar
+   * Kit checker pattern).
+   */
+  onFilesChanged(changes: Array<{ filePath: string; type: 'changed' | 'created' | 'deleted' }>) {
