+          open?: boolean;
+          onOpenChange?: (open: boolean) => void;
+        }
+        const Root = (props: RootProps) => <div />;
+
+        interface ContentProps {
+          /** Trap focus inside dialog */
+          trapFocus?: boolean;
+        }
+        const Content = (props: ContentProps) => <div />;
+
