+        {
+          storyFilePath: filePaths['dialog.stories.tsx'],
+          componentPath: filePaths['dialog.tsx'],
+          exportName: 'Dialog',
+          importId: './dialog',
+          memberAccess: 'Root',
+        },
+        {
+          storyFilePath: filePaths['button.stories.tsx'],
+          componentPath: filePaths['button.tsx'],
+          exportName: 'Button',
