+/**
+ * Discover all value export names from a source file's AST. Used by the docs() helper to build
+ * extraction entries without needing a public "discover exports" method on ComponentMetaProject.
+ */
+function findExportNames(sourceFile: ts.SourceFile): string[] {
+  const names: string[] = [];
+
+  for (const stmt of sourceFile.statements) {
+    // export default X (export assignment)
+    if (ts.isExportAssignment(stmt) && !stmt.isExportEquals) {
+      names.push('default');
+      continue;
+    }
+
+    // export { X, Y, Z } or export { X } from './foo'
+    if (ts.isExportDeclaration(stmt)) {
+      if (stmt.exportClause && ts.isNamedExports(stmt.exportClause)) {
+        for (const spec of stmt.exportClause.elements) {
+          names.push(spec.name.text);
+        }
+      }
+      continue;
+    }
+
+    const mods = ts.canHaveModifiers(stmt) ? ts.getModifiers(stmt) : undefined;
+    if (!mods?.some((m) => m.kind === ts.SyntaxKind.ExportKeyword)) {
+      continue;
+    }
+
+    if (mods.some((m) => m.kind === ts.SyntaxKind.DefaultKeyword)) {
+      names.push('default');
+      continue;
+    }
+
+    if (ts.isFunctionDeclaration(stmt) && stmt.name) {
+      names.push(stmt.name.text);
+    } else if (ts.isClassDeclaration(stmt) && stmt.name) {
+      names.push(stmt.name.text);
+    } else if (ts.isVariableStatement(stmt)) {
+      for (const decl of stmt.declarationList.declarations) {
+        if (ts.isIdentifier(decl.name)) {
+          names.push(decl.name.text);
+        }
+      }
+    } else if (ts.isEnumDeclaration(stmt)) {
+      names.push(stmt.name.text);
+    }
+  }
+
+  return [...new Set(names)];
+}
+
+/**
+ * Extract docs for a test file by its key in TEST_FILES. For each export, creates a minimal story
+ * file with `export default { component: X }` so that Path 2 (resolveFromMetaComponent) fires. This
+ * mirrors production where the user explicitly sets meta.component.
+ */
+function docs(fileName: string): ComponentDoc[] {
+  const fp = filePaths[fileName];
+  if (!fp) {
+    throw new Error(`Unknown test file: "${fileName}"`);
+  }
+
+  // Discover export names from the file's AST
+  const text = sys.readFile(fp);
+  if (!text) {
+    return [];
+  }
+  const sf = ts.createSourceFile(fp, text, ts.ScriptTarget.Latest, true);
+  const exportNames = findExportNames(sf);
+
+  const allDocs: ComponentDoc[] = [];
+  const dir = path.dirname(fp);
+  const baseName = path.basename(fp, path.extname(fp));
+
+  for (const name of exportNames) {
+    // Create a story file that imports and declares meta.component
+    const importLine =
+      name === 'default'
+        ? `import __Component__ from './${baseName}';`
+        : `import { ${name} as __Component__ } from './${baseName}';`;
+
+    const storyContent = `${importLine}\nexport default { component: __Component__ };`;
+    const storyPath = path.join(dir, `${baseName}.__story_${name}__.tsx`);
+
+    sys.writeFile(storyPath, storyContent);
+    project.ensureFiles([storyPath]);
+
+    const entries = [
+      {
+        storyFilePath: storyPath,
+        componentPath: fp,
+        exportName: name,
+      },
+    ];
+
+    const results = project.extractPropsFromStories(entries);
+    const storyMap = results.get(storyPath);
+    if (storyMap) {
+      for (const [, d] of storyMap) {
+        allDocs.push(...d);
+      }
+    }
+  }
+
+  return allDocs;
+}
+
+/** Get detected component export names for a test file. */
+function detectNames(fileName: string): string[] {
+  return docs(fileName)
+    .map((d) => d.exportName)
+    .sort();
+}
